import { ActionSeat, Button, Card, ROW } from "ui";

const body = { flex: 1, minWidth: 0, fontSize: "var(--text-body)" } as const;

/**
 * The action seat for a list row that is not a CardRow (a link row, a row that stacks on a phone),
 * built on ROW: the same seat at the table's width, `narrow`, `default` or `wide`.
 */
export const OnAListRow = () => (
  <Card>
    {(["narrow", "default", "wide"] as const).map((seat, i) => (
      <div key={seat} className={`${i === 0 ? "" : "row-divider "}flex flex-wrap items-center ${ROW}`}>
        <span style={body}>A {seat} seat</span>
        <ActionSeat seat={seat}>
          <Button size="sm" variant="outline">
            Withdraw
          </Button>
        </ActionSeat>
      </div>
    ))}
  </Card>
);
